"""县（区）网店模块——全国县级行政区数据源（市级下区县挂靠）

依据: GB/T 2260 行政区划码(数据源 modood/Administrative-divisions-of-China
pca-code.json, 2023+ 口径), 按"区县码前4位+00 == 市码"归组到
citystore_regions.REGION_CITIES 的 344 市下。

用途:
    - 县(区)网店"申请开店"区县选择(GET /api/citystore/districts/available)
    - apply 区县合法性校验(districtCode 必须在册)

口径:
    - 直辖市(京津沪渝): 所有区县并挂 xx0100 单市条目(含重庆5002县层)
    - 省直辖县级市(济源/仙桃/潜江/天门): 自身单条目, 码=市码重合(白名单)
    - 港澳台(710100/810100/820100): 无县级细分不收录, apply 409 哨兵
    - 神农架429021/海南4690系/新疆兵团6590系: 不在344市口径, 跳过留档
      (与市级网店既有口径一致——这些区域市级也未开放)
    - 生成工具: backend/scripts/gen_citystore_districts.py
"""

from services.citystore_regions import PROVINCES, REGION_CITIES  # noqa: F401

